import re

def parsea_duracion(s):
    if not isinstance(s, str):
        raise ValueError("La duración debe ser una cadena")
    patron = re.fullmatch(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', s)
    if not patron or not s:
        raise ValueError(f"Duración inválida: {s!r}")
    horas, minutos, segundos = patron.groups()
    if horas is None and minutos is None and segundos is None:
        raise ValueError(f"Duración inválida: {s!r}")
    total = 0
    if horas:
        total += int(horas) * 3600
    if minutos:
        total += int(minutos) * 60
    if segundos:
        total += int(segundos)
    return total
```

